mapper.select:
select  
where pos.pos_company_id = #{companyId}
and a.apt_status = #{status}
and a.apt_end_time > #{from}
and a.apt_start_time < #{to}
order by a.apt_start_time, a.apt_id

select slt_id as slotId, slt_interviewer_id as interviewerId,
       date_format(slt_start_time, '%Y-%m-%d %H:%i') as startTime,
       date_format(slt_end_time, '%Y-%m-%d %H:%i') as endTime,
       slt_status as status,
       case when slt_status = 1 then '可用' else '已占用' end as statusLabel
from t_sch_slot where slt_interviewer_id = #{interviewerId}
and slt_end_time > #{from}
and slt_start_time < #{to}
order by slt_start_time

select slt_id as conflictId from t_sch_slot
where slt_interviewer_id = #{interviewerId} and slt_status = 0
  and slt_start_time < #{endTime} and slt_end_time > #{startTime}
and slt_id != #{excludeSlotId}
union all
select apt_id as conflictId from t_sch_appointment
where apt_status in (0, 1)
  and (apt_candidate_id = #{candidateId} or apt_interviewer_id = #{interviewerId})
  and apt_start_time < #{endTime} and apt_end_time > #{startTime}
and apt_id != #{excludeAppointmentId}
